// Typed loader for tools/oracles/expected.json (generated by tools/oracles/emit_expected.py; never edit the JSON by hand).
// Tests compare engine output against these unrounded values, never against the digits printed in DESIGN 9.1.
import data from '../../tools/oracles/expected.json';

export type TolKind = 'rel' | 'abs';

export interface Oracle {
  title: string;
  source: string;
  inputs: Record<string, unknown>;
  values: Record<string, number>;
  units: Record<string, string>;
  tol: number;
  tolKind: TolKind;
  /** Per-value tolerance overrides (e.g. PS-15 angles). */
  tols?: Record<string, { tol: number; tolKind: TolKind }>;
  /** DESIGN 9.1 as printed (documentation/consistency only; do not test against it). */
  printed: Record<string, number>;
  printedHalfUlp: Record<string, number>;
  note?: string;
}

export interface Expected {
  meta: { generator: string; numpy: string; scipy: string; note: string };
  oracles: Record<string, Oracle>;
  levels: Record<string, any>;
}

export const expected = data as unknown as Expected;

export function oracleIds(): string[] {
  return Object.keys(expected.oracles);
}

export function oracle(id: string): Oracle {
  const o = expected.oracles[id];
  if (!o) throw new Error(`oracle: unknown id "${id}" (known: ${oracleIds().join(', ')})`);
  return o;
}

export function oracleValue(id: string, name: string): number {
  const o = oracle(id);
  const v = o.values[name];
  if (typeof v !== 'number') throw new Error(`oracle ${id}: unknown value "${name}" (known: ${Object.keys(o.values).join(', ')})`);
  return v;
}

export function oracleTol(id: string, name: string): { tol: number; tolKind: TolKind } {
  const o = oracle(id);
  return o.tols?.[name] ?? { tol: o.tol, tolKind: o.tolKind };
}

/** Throws unless |actual - expected| is within the oracle's tolerance (relative or absolute per row / per value). */
export function expectOracle(id: string, name: string, actual: number, tolOverride?: { tol: number; tolKind: TolKind }): void {
  const e = oracleValue(id, name);
  const { tol, tolKind } = tolOverride ?? oracleTol(id, name);
  const err = tolKind === 'abs' || e === 0 ? Math.abs(actual - e) : Math.abs(actual - e) / Math.abs(e);
  if (!(err <= tol)) {
    throw new Error(`oracle ${id}.${name}: actual ${actual} vs expected ${e} (${tolKind} error ${err} > tol ${tol})`);
  }
}

export function level(id: string): any {
  const l = expected.levels[id];
  if (!l) throw new Error(`oracle level: unknown id "${id}"`);
  return l;
}
